const XLSX = require('xlsx');
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, HeadingLevel } = require('docx');
const fs = require('fs');

// Read inventory data
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const products = XLSX.utils.sheet_to_json(wb.Sheets['Products']);

// Helper: create a styled cell
function cell(text, opts = {}) {
  return new TableCell({
    children: [
      new Paragraph({
        children: [
          new TextRun({
            text: String(text),
            bold: opts.bold || false,
            size: 22,
            font: 'Calibri',
          }),
        ],
        alignment: opts.align || AlignmentType.LEFT,
      }),
    ],
    width: opts.width ? { size: opts.width, type: WidthType.PERCENTAGE } : undefined,
    shading: opts.shading ? { fill: opts.shading } : undefined,
    margins: { top: 40, bottom: 40, left: 80, right: 80 },
  });
}

// Build table rows
const headerRow = new TableRow({
  children: [
    cell('#', { bold: true, shading: '2E74B5', width: 8 }),
    cell('Product Name', { bold: true, shading: '2E74B5', width: 42 }),
    cell('Category', { bold: true, shading: '2E74B5', width: 20 }),
    cell('Price', { bold: true, shading: '2E74B5', width: 15, align: AlignmentType.RIGHT }),
    cell('In Stock', { bold: true, shading: '2E74B5', width: 15, align: AlignmentType.CENTER }),
  ],
});

const dataRows = products.map((p, i) => {
  const shade = i % 2 === 0 ? 'F2F2F2' : 'FFFFFF';
  return new TableRow({
    children: [
      cell(i + 1, { shading: shade, width: 8 }),
      cell(p['Name'], { shading: shade, width: 42 }),
      cell(p['Category'], { shading: shade, width: 20 }),
      cell(`$${p['Price']}`, { shading: shade, width: 15, align: AlignmentType.RIGHT }),
      cell(p['In Stock'], { shading: shade, width: 15, align: AlignmentType.CENTER }),
    ],
  });
});

// Category breakdown
const categories = {};
products.forEach(p => {
  const cat = p['Category'];
  categories[cat] = (categories[cat] || 0) + 1;
});
const catSummary = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, count]) => `${cat} (${count})`)
  .join(', ');

const prices = products.map(p => p['Price']).filter(p => p > 0);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);

// Build document
const doc = new Document({
  sections: [
    {
      children: [
        new Paragraph({
          children: [new TextRun({ text: 'Product Inventory Summary', bold: true, size: 36, font: 'Calibri', color: '2E74B5' })],
          alignment: AlignmentType.CENTER,
          spacing: { after: 120 },
        }),
        new Paragraph({
          children: [new TextRun({ text: `Generated on: ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}`, italics: true, size: 20, font: 'Calibri', color: '666666' })],
          alignment: AlignmentType.CENTER,
          spacing: { after: 300 },
        }),

        // Overview
        new Paragraph({ text: 'Overview', heading: HeadingLevel.HEADING_2, spacing: { after: 120 } }),
        new Paragraph({
          children: [new TextRun({ text: `The inventory contains ${products.length} products across ${Object.keys(categories).length} categories: ${catSummary}. All items are currently in stock. Prices range from $${minPrice} to $${maxPrice}, with an average of $${avgPrice} (excluding promotional items).`, size: 22, font: 'Calibri' })],
          spacing: { after: 300 },
        }),

        // Table
        new Paragraph({ text: 'Product Details', heading: HeadingLevel.HEADING_2, spacing: { after: 120 } }),
        new Table({
          rows: [headerRow, ...dataRows],
          width: { size: 100, type: WidthType.PERCENTAGE },
        }),

        // Footer note
        new Paragraph({
          children: [new TextRun({ text: `\nNote: All ${products.length} products are marked as "In Stock." The AUTUMN10 Cart Discount is a promotional entry with a $0 price.`, italics: true, size: 20, font: 'Calibri', color: '888888' })],
          spacing: { before: 200 },
        }),
      ],
    },
  ],
});

// Write to file
Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/workspace/data/inventory_summary.docx', buffer);
  console.log('Document saved: /workspace/data/inventory_summary.docx');
});
